def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def find(color):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    return r, c
        return None

    paths = {}

    # Color 1: short rightward track ending one row up.
    p = find(1)
    if p:
        r, c = p
        paths[1] = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
        for rr, cc in paths[1]:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 1 if (rr, cc) in ((r, c), (r - 1, c + 2)) else 5

    # Color 2: horizontal track extending four cells to the left.
    p = find(2)
    if p:
        r, c = p
        paths[2] = [(r, cc) for cc in range(c - 4, c + 1)]
        for rr, cc in paths[2]:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 2 if cc in (c - 4, c) else 5

    # Color 3: vertical track extending three cells down.
    p = find(3)
    if p:
        r, c = p
        paths[3] = [(rr, c) for rr in range(r, r + 4)]
        for rr, cc in paths[3]:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 3 if rr in (r, r + 3) else 5

    # Color 6: vertical track extending six cells up.
    p = find(6)
    if p:
        r, c = p
        paths[6] = [(rr, c) for rr in range(r - 6, r + 1)]
        for rr, cc in paths[6]:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 6 if rr in (r - 6, r) else 5

    # Where a horizontal 2-track meets a vertical 3- or 6-track,
    # mark the crossing and continue diagonally down-left in color 4.
    if 2 in paths:
        for color in (3, 6):
            if color in paths:
                crossings = set(paths[2]) & set(paths[color])
                for r, c in crossings:
                    rr, cc = r, c
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 4
                        rr += 1
                        cc -= 1

    return out
